CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE memberships (organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL, PRIMARY KEY(organization_id,user_id));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), organization_id TEXT NOT NULL REFERENCES organizations(id), expires_at INTEGER NOT NULL);
CREATE TABLE clients (organization_id TEXT NOT NULL REFERENCES organizations(id), id TEXT NOT NULL, name TEXT NOT NULL, email TEXT NOT NULL, normalized_email TEXT NOT NULL, company TEXT NOT NULL, notes TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(organization_id,id), UNIQUE(organization_id,normalized_email));
CREATE TABLE records (organization_id TEXT NOT NULL REFERENCES organizations(id), id TEXT NOT NULL, kind TEXT NOT NULL, assignee_user_id TEXT REFERENCES users(id), client_id TEXT, project_id TEXT, employee_id TEXT, lead_id TEXT, payload TEXT NOT NULL, PRIMARY KEY(organization_id,id), FOREIGN KEY(organization_id,client_id) REFERENCES clients(organization_id,id), FOREIGN KEY(organization_id,project_id) REFERENCES records(organization_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(organization_id,employee_id) REFERENCES records(organization_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(organization_id,lead_id) REFERENCES records(organization_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE conversions (organization_id TEXT NOT NULL, lead_id TEXT NOT NULL, client_id TEXT NOT NULL, project_id TEXT, task_id TEXT, PRIMARY KEY(organization_id,lead_id), FOREIGN KEY(organization_id,lead_id) REFERENCES records(organization_id,id), FOREIGN KEY(organization_id,client_id) REFERENCES clients(organization_id,id), FOREIGN KEY(organization_id,project_id) REFERENCES records(organization_id,id), FOREIGN KEY(organization_id,task_id) REFERENCES records(organization_id,id));
CREATE TABLE onboarding (organization_id TEXT NOT NULL, client_id TEXT NOT NULL, id TEXT NOT NULL, title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(organization_id,id), UNIQUE(organization_id,client_id,title), FOREIGN KEY(organization_id,client_id) REFERENCES clients(organization_id,id));
CREATE TABLE audit_events (id INTEGER PRIMARY KEY AUTOINCREMENT, organization_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), action TEXT NOT NULL, record_id TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit events are append only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'Audit events are append only'); END;
CREATE TABLE auth_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE INDEX records_org_kind ON records(organization_id,kind);
CREATE INDEX audit_org ON audit_events(organization_id,id);
